from format_lecon import Lesson,paras,steps,table
from diagnostics import comparison
l=Lesson('Ronflement')
l.add('Le {ronflement est un bruit respiratoire produit pendant le sommeil}. Il correspond à la vibration de tissus des voies aériennes supérieures. Il peut être isolé ou accompagner un trouble respiratoire du sommeil.',paras('Un ronflement ne prouve ni une apnée ni son absence. Le terme de ronflement primaire suppose une évaluation qui ne retrouve pas de trouble respiratoire pathologique expliquant le bruit.', 'Un bruit aigu avec gêne respiratoire à l’éveil évoque une autre situation, notamment un stridor : il faut alors évaluer immédiatement les voies aériennes. L’intensité sonore rapportée par le partenaire ne mesure pas la gravité physiologique.'),(1,3,5))
l.add('Le {contexte modifie la probabilité et le risque}. Âge, obésité, anatomie, alcool et médicaments interviennent chez l’adulte. Chez l’enfant, les végétations et les amygdales prennent une place importante.',paras('Les dix diagnostics sont une sélection pédagogique : ils associent syndrome, causes anatomiques et maladies favorisantes. Ils ne sont ni mutuellement exclusifs ni classés selon une prévalence suisse mesurée.', 'Le ronflement persistant de l’enfant mérite une évaluation, même sans somnolence. Agitation, hyperactivité et difficultés scolaires peuvent traduire un sommeil fragmenté.', 'La grossesse, une profession nécessitant une vigilance constante et une maladie cardiovasculaire instable accélèrent le bilan. Les critères de priorité britanniques éclairent le risque médical mais ne constituent pas une règle administrative suisse.'),(1,2,4,5))
an=l.subwindow('anatomie','Collapsibilité pharyngée, résistance nasale et commande ventilatoire',paras('Le pharynx est un conduit souple. La baisse du tonus musculaire pendant le sommeil favorise son rétrécissement, surtout lorsque les tissus environnants ou la morphologie osseuse réduisent déjà l’espace disponible.', 'Une obstruction nasale augmente la résistance inspiratoire et favorise la respiration buccale. Elle peut contribuer au ronflement sans expliquer à elle seule toutes les apnées : les étages nasal, palatin et rétrolingual peuvent être associés.', 'Une apnée obstructive conserve des efforts respiratoires alors que le débit est interrompu. Une apnée centrale correspond à une diminution de la commande ventilatoire ; une hypoventilation ne se résume pas à des pauses isolées.', 'La répétition des événements peut entraîner hypoxémie intermittente et fragmentation du sommeil. Les conséquences dépendent aussi des symptômes, des comorbidités et du terrain, pas uniquement d’un index.'),(1,3,4))
l.add('Les {bases physiologiques relient vibration et obstruction}. Le bruit naît d’un passage d’air rétréci. Une fermeture complète, une hypopnée et une hypoventilation demandent des mesures différentes.',paras(an),(1,3,4))
l.add('Le {tri recherche d’abord un danger respiratoire ou accidentel}. Une détresse à l’éveil n’attend pas un enregistrement nocturne. Une somnolence au volant impose de cesser de conduire et d’obtenir un avis rapide.',table(['🚩 Situation','Conduite'],[['Cyanose, détresse respiratoire, trouble de conscience.','Urgence immédiate ; en Suisse appeler le 144 selon la situation.'],['Endormissement au volant, quasi-accident, poste de sécurité.','Écarter l’exposition au risque et accélérer l’évaluation spécialisée.'],['Obésité avec hypoxémie à l’éveil ou suspicion d’hypercapnie.','Rechercher une hypoventilation ; bilan ventilatoire, sans retard en cas de décompensation.'],['Enfant avec efforts marqués, pauses, retard de croissance ou terrain syndromique.','Évaluation pédiatrique spécialisée prioritaire selon gravité.'],['Obstruction nasale unilatérale progressive, saignements, signes orbitaires ou neurologiques.','Avis ORL rapide ; urgence si complication visuelle ou neurologique.'],['Maladie cardiovasculaire instable, grossesse, chirurgie majeure prévue.','Signaler le risque de trouble respiratoire et organiser le bilan adapté.']]),(1,2,3,4,7,8))
l.add('L’{anamnèse associe récit du patient et observations nocturnes}. Préciser ancienneté, fréquence, position, pauses et étouffements. Rechercher sommeil non réparateur, céphalées matinales, nycturie et fatigue.',paras('Demander horaires et durée du sommeil, insomnie, somnolence involontaire, conduite et profession. Un score d’Epworth normal n’exclut pas des apnées. Un questionnaire de risque guide le bilan sans remplacer l’enregistrement.', 'Noter poids et évolution, alcool, hypnotiques, opioïdes et autres médicaments. Une adaptation d’un traitement prescrit se décide avec le prescripteur ; ne pas recommander un sevrage brutal.', 'Interroger sur obstruction nasale, allergie, traumatisme, chirurgie, dentition, signes thyroïdiens ou modification des traits. Chez l’enfant : respiration buccale, énurésie, comportement, croissance et difficultés de déglutition.'),(1,2,4,5))
l.add('L’{examen étudie plusieurs étages des voies aériennes}. Mesurer poids, taille, pression artérielle et observer la respiration. Examiner nez, bouche, amygdales, langue et position mandibulaire.',paras('L’examen recherche rhinite, déviation septale, masse, hypertrophie lymphoïde, macroglossie et rétrognathie. Un examen diurne normal ne prouve pas la perméabilité pendant le sommeil.', 'Mesurer l’oxygénation et rechercher signes cardiorespiratoires si le terrain le justifie. Chez l’enfant, apprécier courbes de croissance et contexte syndromique ; la taille visible des amygdales ne quantifie pas seule l’obstruction nocturne.', 'Une endoscopie ORL précise les obstacles selon l’indication. Une endoscopie sous sommeil induit répond à une question thérapeutique spécialisée ; elle n’est pas le dépistage initial de tout ronflement.'),(1,2,3,4,6))
l.add('Le {tableau différentiel organise les hypothèses}. Une rhinite ou une anomalie mandibulaire peut coexister avec un syndrome d’apnées. Une maladie rare est retenue pour ses signes d’appel ou sa gravité.',comparison(),(1,2,3,4,5,6,8))
l.add('Le {diagnostic distingue bruit isolé et trouble respiratoire}. Les questionnaires ne suffisent pas à confirmer ni à exclure une apnée. L’indice respiratoire s’interprète avec symptômes et qualité technique.',paras('La polygraphie mesure notamment débit, effort et oxygénation. La polysomnographie ajoute l’analyse du sommeil ; le dénominateur et les critères de cotation peuvent faire varier l’indice d’apnées-hypopnées.', 'Un résultat négatif ne clôt pas le bilan si la suspicion persiste. Le diagnostic de ronflement primaire doit être reconsidéré si apparaissent pauses, fatigue ou facteurs de risque.', 'Les seuils et critères pédiatriques ne sont pas ceux de l’adulte. Les recommandations suisses soulignent une présentation et des moyens d’évaluation dépendant de l’âge.'),(1,2,4))
l.add('Les {examens complémentaires répondent à la question clinique}. La polygraphie peut être réalisée à domicile chez l’adulte sélectionné. Une polysomnographie s’impose selon complexité ou discordance.',paras('En Suisse, l’oxymétrie seule a une place de dépistage et ne remplace pas le diagnostic complet. NICE la propose comme solution d’accès limité chez certains adultes, avec recours à un examen plus complet si négative malgré des symptômes ; cela ne justifie pas de rassurer sur un résultat isolé.', 'Si hypoventilation suspectée, les gaz sanguins à l’éveil et, selon indication, la mesure nocturne du dioxyde de carbone complètent le bilan. Ne pas retarder le traitement d’une insuffisance ventilatoire aiguë pour obtenir ces examens.', 'Les dosages thyroïdiens ou de facteur de croissance sont ciblés sur les signes et le contexte. Imagerie et biopsie concernent une lésion suspecte ; aucun scanner ni bilan hormonal large n’est requis pour chaque ronfleur.'),(1,4,7))
l.add('L’{algorithme fait passer le risque avant le traitement du bruit}. Séparer urgence, suspicion d’apnées et ronflement isolé. Adapter ensuite le traitement aux mécanismes documentés.',steps('Évaluer respiration à l’éveil, vigilance, conduite et alarmes ORL ou pédiatriques.', 'Recueillir histoire du sommeil, facteurs favorisants et examen des voies aériennes.', 'Si apnées ou hypoventilation possibles, orienter vers une exploration adaptée et traiter les urgences sans attendre.', 'Identifier les causes nasales, lymphoïdes, craniofaciales ou endocriniennes sans supposer leur exclusivité.', 'Choisir une intervention proportionnée, documenter son efficacité et réévaluer les symptômes résiduels.'),(1,2,3,4,7,8))
l.add('La {prise en charge suisse traite le mécanisme et le retentissement}. Mesures de mode de vie et traitement d’une cause nasale accompagnent le parcours. La pression positive ou une orthèse répondent à une indication documentée.',paras('Chez l’adulte en surpoids, accompagner la réduction pondérale ; réduire l’alcool, améliorer le sommeil et réviser les médicaments aggravants. Ces mesures ne doivent pas retarder le traitement d’apnées sévères ou d’une somnolence dangereuse.', 'La pression positive continue est un traitement de référence des apnées obstructives. L’orthèse d’avancement mandibulaire nécessite un bilan dentaire et une vérification de l’efficacité. Les recommandations suisses la permettent en première intention dans certaines formes légères ou modérées. NICE la situe surtout après refus ou intolérance de la pression positive.', 'L’enfant avec hypertrophie adénoamygdalienne et obstruction significative suit un parcours pédiatrique spécifique. La chirurgie n’est pas automatique pour tout ronflement ; des apnées peuvent persister après intervention.', 'Il n’existe pas ici de prescription médicamenteuse universelle contre le bruit. Les traitements d’une rhinite, d’une hypothyroïdie ou d’une acromégalie relèvent de leur indication et de l’information professionnelle suisse. Un spray, une sédation ou un dispositif vendu sans bilan ne remplace pas le traitement d’apnées.'),(1,2,4,6))
l.add('La {prévention inclut un suivi de l’efficacité réelle}. Un bruit réduit ne prouve pas la disparition des apnées. Contrôler symptômes, tolérance, observance et données respiratoires selon le traitement.',paras('Pour la pression positive, les recommandations suisses prévoient un contrôle médical au plus tard à trois mois, plus tôt autant que nécessaire pendant l’adaptation ; NICE recommande un premier contact dans le mois. Organiser un accès rapide si difficulté de masque ou sécheresse plutôt que laisser abandonner le dispositif.', 'Après orthèse ajustée, un enregistrement vérifie généralement l’efficacité ; la recommandation suisse prévoit une exception dans une forme légère devenue asymptomatique. Un suivi dentaire reste nécessaire.', 'Chez l’enfant, revoir les symptômes et contrôler les formes sévères ou les signes persistants après chirurgie. Pour la conduite, appliquer le cadre suisse avec l’équipe compétente ; les règles britanniques ne sont pas transposées.'),(1,2,4))
l.add('Le {point clé est de ne pas confondre silence et respiration normale}. Un ronflement banal en apparence peut révéler des apnées. Une prise en charge efficace protège aussi la vigilance et le fonctionnement quotidien.',paras('Rechercher les mécanismes réversibles sans manquer une cause grave. Les maladies endocriniennes et les tumeurs sont orientées par des signes associés ; elles ne justifient pas une exploration indifférenciée de tous les ronfleurs.', 'Le parcours pédiatrique est distinct du parcours adulte. La disparition du bruit après un traitement nasal ne permet pas d’arrêter un traitement ventilatoire sans réévaluation.'),(1,2,3,4))
l.quiz([('Le ronflement prouve-t-il une apnée ?','Non.'),('Un ronflement très fort mesure-t-il la gravité ?','Non, il faut évaluer les conséquences et les événements respiratoires.'),('Un score d’Epworth normal exclut-il les apnées ?','Non.'),('Que faire en cas d’endormissement au volant ?','Cesser de conduire et obtenir une évaluation rapide.'),('Une détresse respiratoire attend-elle une polysomnographie ?','Non, elle impose une prise en charge immédiate.'),('L’enfant apnéique est-il toujours somnolent ?','Non, il peut être agité ou hyperactif.'),('Les seuils pédiatriques sont-ils ceux de l’adulte ?','Non.'),('Une oxymétrie normale suffit-elle à exclure les apnées ?','Non.'),('Une polygraphie négative clôt-elle toujours le bilan ?','Non, une discordance clinique peut conduire à une polysomnographie.'),('Rhinite et apnées peuvent-elles coexister ?','Oui.'),('Une obstruction unilatérale avec épistaxis est-elle banale ?','Non, elle demande une évaluation ORL.'),('Faut-il arrêter brutalement un hypnotique prescrit ?','Non, une adaptation se décide avec le prescripteur.'),('Une orthèse demande-t-elle un bilan dentaire ?','Oui, ainsi qu’un suivi de tolérance et d’efficacité.'),('La disparition du bruit prouve-t-elle la guérison des apnées ?','Non.')],(1,2,3,4,5,6,7))
l.write()
